// Turns the Sheets API grid (values + background colours) into one item per highlighted row.
const cfg = $('Config').first().json;
const resp = $input.first().json;
if (!resp || !resp.sheets || !resp.sheets.length) {
  throw new Error(`Tab "${cfg.sheetName}" not found in spreadsheet ${cfg.spreadsheetId}. Check Config → sheetName.`);
}
const sheet = resp.sheets[0];
const data = (sheet.data && sheet.data[0]) || {};
const startRow = data.startRow || 0;
const rowData = data.rowData || [];

// --- target colour (#eae287) → 0..1 floats, compared per channel ---
const hex = String(cfg.highlightHex || '#eae287').replace('#', '');
const target = [0, 2, 4].map(i => parseInt(hex.substr(i, 2), 16) / 255);
const tol = Number(cfg.colorTolerance || 0.03);
const isTargetColor = (bg) => {
  if (!bg) return false;
  const c = [bg.red || 0, bg.green || 0, bg.blue || 0];
  return c.every((v, i) => Math.abs(v - target[i]) <= tol);
};
const cellBg = (cell) => cell && cell.effectiveFormat && cell.effectiveFormat.backgroundColor;
const cellVal = (cell) => (cell && cell.formattedValue !== undefined && cell.formattedValue !== null) ? String(cell.formattedValue).trim() : '';
const colLetter = (idx) => { let s = ''; idx += 1; while (idx > 0) { const m = (idx - 1) % 26; s = String.fromCharCode(65 + m) + s; idx = Math.floor((idx - 1) / 26); } return s; };

// --- header row ---
const headerCells = (rowData[0] && rowData[0].values) || [];
const headers = headerCells.map(cellVal);
const norm = (s) => String(s || '').toLowerCase().trim();
const findCol = (...cands) => {
  for (const c of cands) {
    const i = headers.findIndex(h => norm(h) === c);
    if (i >= 0) return i;
  }
  for (const c of cands) {
    const i = headers.findIndex(h => norm(h).startsWith(c));
    if (i >= 0) return i;
  }
  return -1;
};
const src = {
  company: findCol('company / person name', 'company', 'bedrijf', 'naam'),
  phone: findCol('phone', 'telefoon'),
  email: findCol('email', 'e-mail'),
  sector: findCol('sector', 'branche', 'industry'),
  street: findCol('street address', 'adres', 'street'),
  postcode: findCol('postcode', 'zip'),
  city: findCol('city', 'plaats', 'stad'),
  facebook: findCol('facebook'),
  instagram: findCol('instagram'),
};
if (src.company < 0 || src.email < 0) {
  throw new Error(`Could not find the company/email columns. Headers seen: ${headers.join(' | ')}`);
}

// --- status columns (created after the last header when missing) ---
const wanted = [
  ['status', 'Status'],
  ['sentAt', 'Verzonden op'],
  ['firstName', 'Voornaam'],
  ['nameSource', 'Naam bron'],
  ['error', 'Fout'],
];
let nextFree = headers.length;
while (nextFree > 0 && !headers[nextFree - 1]) nextFree--;
const cols = {};
for (const [key, label] of wanted) {
  let idx = headers.findIndex(h => norm(h) === norm(label));
  const missing = idx < 0;
  if (missing) { idx = nextFree++; }
  cols[key] = { idx, col: colLetter(idx), header: label, missing };
}

// --- rows ---
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const out = [];
for (let r = 1; r < rowData.length; r++) {
  const cells = (rowData[r] && rowData[r].values) || [];
  const get = (i) => (i >= 0 ? cellVal(cells[i]) : '');
  const company = get(src.company);
  if (!company) continue;
  const highlighted = isTargetColor(cellBg(cells[src.company])) || isTargetColor(cellBg(cells[src.email]));
  const emailRaw = get(src.email);
  const email = emailRaw.toLowerCase().replace(/^mailto:/, '').split(/[;,\s]/)[0] || '';
  out.push({
    json: {
      row: startRow + r + 1,          // 1-based sheet row number
      highlighted,
      company,
      email,
      emailValid: emailRe.test(email),
      phone: get(src.phone),
      sector: get(src.sector),
      street: get(src.street),
      postcode: get(src.postcode),
      city: get(src.city),
      facebook: get(src.facebook),
      instagram: get(src.instagram),
      status: get(cols.status.idx),
      sentAt: get(cols.sentAt.idx),
      firstName: get(cols.firstName.idx),
      nameSource: get(cols.nameSource.idx),
      _cols: cols,
      _sheetName: sheet.properties.title,
    },
  });
}
const nHi = out.filter(i => i.json.highlighted).length;
if (!out.length) throw new Error('No data rows found under the header row.');
// Attach a small summary to every item so it is visible in the execution log.
for (const i of out) i.json._summary = `${out.length} rows read, ${nHi} highlighted (${cfg.highlightHex})`;
return out;

// Send mode: choose exactly ONE row per run (the schedule fires every 5 minutes).
const cfg = $('Config').first().json;
const rows = $input.all().map(i => i.json);
const isDone = (r) => /^verzonden/i.test(r.status || '') || /^fout/i.test(r.status || '');
const candidates = rows.filter(r => r.highlighted && r.emailValid && !isDone(r));
const skippedBadEmail = rows.filter(r => r.highlighted && !r.emailValid && !isDone(r)).length;
if (!candidates.length) {
  // Nothing left to send: end this run quietly.
  return [];
}
const next = candidates[0];
next._remainingAfterThis = candidates.length - 1;
next._skippedInvalidEmail = skippedBadEmail;
next.testMode = !!cfg.testMode;
next.to = cfg.testMode ? cfg.testEmail : next.email;
return [{ json: next }];

// Builds subject + HTML body for one lead. Text is kept verbatim from the approved template.
const cfg = $('Config').first().json;
const r = $input.first().json;
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const company = esc(r.company);
const firstName = esc((r.firstName || '').trim());
const greeting = firstName ? `Beste ${firstName},` : `Beste ${company},`;
const subject = (r.testMode ? '[TEST] ' : '') + `Gratis website-ontwerp voor ${r.company}`;

const p = (t) => `<p style="margin:0 0 16px">${t}</p>`;
const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#1A1613;max-width:640px">
${p(greeting)}
${p(`Mijn naam is Wouter Altepost, oprichter van Alpaca AI hier uit Amsterdam. Ik zag dat ${company} nog geen eigen website heeft, en dat leek me zonde voor een zaak met zo'n herkenbare uitstraling.`)}
${p(`Ik kan <strong>binnen een dag een <em>gratis</em> ontwerp voor je klaarzetten</strong>, in de stijl van jullie zaak. <strong>Geen verplichting en geen kosten.</strong> Daarna plannen we, wanneer het jou uitkomt, een kort en vrijblijvend telefoontje om het samen door te nemen en eventuele wijzigingen te bespreken, ook dat helemaal gratis.`)}
${p(`Mocht je enthousiast zijn: kunnen we het ontwerp binnen een week omzetten in een live website. Dat is eenmalig 595 euro, verder geen abonnement verplicht, en ik koppel hem aan je Google Bedrijfsprofiel en Facebook-pagina, zodat je reviews, openingstijden en berichten automatisch op de site komen te staan.`)}
${p(`Laat het weten als je interesse hebt, dan zet ik een voorbeeld voor je klaar.`)}
<p style="margin:24px 0 12px">Met vriendelijke groet,</p>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse">
<tr>
<td style="vertical-align:top;padding:0 18px 0 0;border-right:1px solid #E8E2D8"><img src="${cfg.logoUrl}" alt="Alpaca AI" width="110" style="display:block;width:110px;height:auto"></td>
<td style="vertical-align:top;padding:0 0 0 18px;font-size:14px;line-height:1.5">
<strong style="color:#1A1613">Wouter Altepost</strong><br>
<span style="color:#6B655D">Alpaca AI</span><br>
<a href="mailto:wout@alpacaai.nl" style="color:#1A1613;text-decoration:none">wout@alpacaai.nl</a><br>
<a href="https://alpacaai.nl/diensten" style="color:#F09537;text-decoration:none">alpacaai.nl/diensten</a><br>
<a href="tel:+31628283985" style="color:#1A1613;text-decoration:none">06 28 28 39 85</a>
</td>
</tr>
</table>
<hr style="border:none;border-top:1px solid #EEE;margin:24px 0 12px">
<p style="color:#A39D94;font-size:12px;line-height:1.5;margin:0">Privacyverklaring: <a href="https://alpacaai.nl/privacy" style="color:#A39D94">alpacaai.nl/privacy</a>. Wil je dit soort berichten niet ontvangen? Laat het gewoon weten, dan verwijder ik je gegevens meteen en stuur ik niets meer.</p>
</div>`;

return [{ json: { ...r, subject, html, greeting } }];

const r = $('Code · Build email').first().json;  // Gmail outputs its API response, so take the lead from the previous node
if (r.testMode) { return []; }  // test sends are never recorded in the sheet
const sheetName = r._sheetName; const cols = r._cols;

// Builds the values:batchUpdate payload. Also writes any missing status headers on row 1.
const cfg = $('Config').first().json;
const cellRange = (col, row) => `'${sheetName}'!${col}${row}`;
const data = [];
for (const key of Object.keys(cols)) {
  if (cols[key].missing) data.push({ range: cellRange(cols[key].col, 1), values: [[cols[key].header]] });
}

const now = new Date().toLocaleString('nl-NL', { timeZone: 'Europe/Amsterdam', hour12: false });
data.push({ range: cellRange(cols.status.col, r.row), values: [['Verzonden']] });
data.push({ range: cellRange(cols.sentAt.col, r.row), values: [[now]] });
data.push({ range: cellRange(cols.error.col, r.row), values: [['']] });
return [{ json: { row: r.row, body: { valueInputOption: 'USER_ENTERED', data } } }];

const src = $('Code · Build email').first().json;
const errItem = $input.first().json;
const msg = (errItem.error && (errItem.error.message || errItem.error)) || 'Onbekende fout';
if (src.testMode) { throw new Error('Test send failed: ' + msg); }
const sheetName = src._sheetName; const cols = src._cols;
const r = src;

// Builds the values:batchUpdate payload. Also writes any missing status headers on row 1.
const cfg = $('Config').first().json;
const cellRange = (col, row) => `'${sheetName}'!${col}${row}`;
const data = [];
for (const key of Object.keys(cols)) {
  if (cols[key].missing) data.push({ range: cellRange(cols[key].col, 1), values: [[cols[key].header]] });
}

const now = new Date().toLocaleString('nl-NL', { timeZone: 'Europe/Amsterdam', hour12: false });
data.push({ range: cellRange(cols.status.col, r.row), values: [['Fout']] });
data.push({ range: cellRange(cols.error.col, r.row), values: [[`${now}: ${String(msg).slice(0, 400)}`]] });
return [{ json: { row: r.row, body: { valueInputOption: 'USER_ENTERED', data } } }];

// Enrich mode: every highlighted row that has no first name yet and has not been searched before.
const rows = $input.all().map(i => i.json);
const todo = rows.filter(r => r.highlighted && r.emailValid && !r.firstName && !r.nameSource && !/^verzonden/i.test(r.status || ''));
return todo.map(r => ({ json: r }));

