// Reads the JSON object out of Claude's reply; falls back to "not found" on any problem.
const lead = $('Code · Rows to enrich').item.json;
const resp = $input.item.json;
let result = { first_name: null, full_name: null, role: null, confidence: 0, source_url: null, reasoning: '' };
let note = '';
try {
  if (resp.error) {
    note = 'API-fout: ' + (resp.error.message || resp.error.error?.message || JSON.stringify(resp.error)).slice(0, 200);
  } else if (resp.stop_reason === 'refusal') {
    note = 'Geweigerd door model';
  } else {
    const texts = (resp.content || []).filter(b => b.type === 'text').map(b => b.text);
    const last = texts.length ? texts[texts.length - 1] : '';
    const m = last.match(/\{[\s\S]*\}/);
    if (m) {
      const parsed = JSON.parse(m[0]);
      result = { ...result, ...parsed };
    } else {
      note = 'Geen JSON in antwoord';
    }
    if (resp.stop_reason === 'pause_turn' || resp.stop_reason === 'max_tokens') note = note || `stop_reason=${resp.stop_reason}`;
  }
} catch (e) {
  note = 'Parsefout: ' + String(e.message).slice(0, 120);
}
const conf = Number(result.confidence) || 0;
const clean = (s) => String(s || '').trim();
let firstName = clean(result.first_name);
// Safety net: only accept plausible name tokens with confidence >= 70.
if (conf < 70 || !/^[A-Za-zÀ-ÿ' -]{2,30}$/.test(firstName) || /^(null|none|onbekend|unknown)$/i.test(firstName)) firstName = '';
const parts = [];
parts.push(firstName ? `${conf}%` : `niet gevonden (${conf}%)`);
if (clean(result.full_name)) parts.push(clean(result.full_name) + (clean(result.role) ? ` · ${clean(result.role)}` : ''));
if (clean(result.source_url)) parts.push(clean(result.source_url));
if (clean(result.reasoning)) parts.push(clean(result.reasoning));
if (note) parts.push(note);
return { json: { ...lead, firstName, nameSource: parts.join(' | ').slice(0, 480) } };

const r = $input.item.json;
const sheetName = r._sheetName; const cols = r._cols;

// Builds the values:batchUpdate payload. Also writes any missing status headers on row 1.
const cfg = $('Config').first().json;
const cellRange = (col, row) => `'${sheetName}'!${col}${row}`;
const data = [];
for (const key of Object.keys(cols)) {
  if (cols[key].missing) data.push({ range: cellRange(cols[key].col, 1), values: [[cols[key].header]] });
}

data.push({ range: cellRange(cols.firstName.col, r.row), values: [[r.firstName || '']] });
data.push({ range: cellRange(cols.nameSource.col, r.row), values: [[r.nameSource || '']] });
return { json: { row: r.row, body: { valueInputOption: 'USER_ENTERED', data } } };
